import { context, createContextKey } from "@opentelemetry/api";
const LEGACY_CONVERSATION_ID_KEYS = ["cursor.conversation.id"];
const conversationIdKey = createContextKey("cursor.conversation.id");
const conversationIdKeysKey = createContextKey("agent_sdk.conversation_id_keys");
/**
 * Bind the BDK session id onto a context. The value does not propagate.
 * `keys` are the span attributes the processor copies it to.
 */
export function withConversationId(parent, sessionId, keys = LEGACY_CONVERSATION_ID_KEYS) {
    return parent.setValue(conversationIdKey, sessionId).setValue(conversationIdKeysKey, keys);
}
function conversationIdFrom(ctx) {
    const value = ctx.getValue(conversationIdKey);
    return typeof value === "string" && value !== "" ? value : undefined;
}
function conversationIdKeysFrom(ctx) {
    const value = ctx.getValue(conversationIdKeysKey);
    return Array.isArray(value) && value.every((key) => typeof key === "string")
        ? value
        : LEGACY_CONVERSATION_ID_KEYS;
}
/** Session id for the active turn, when this process set one. */
export function currentConversationId() {
    return conversationIdFrom(context.active());
}
/** Copy the session id onto a span that does not already set it. */
export function conversationIdSpanProcessor() {
    return {
        onStart(span, parentContext) {
            const value = conversationIdFrom(parentContext);
            if (value === undefined) {
                return;
            }
            for (const key of conversationIdKeysFrom(parentContext)) {
                if (span.attributes[key] === undefined) {
                    span.setAttribute(key, value);
                }
            }
        },
        onEnd() { },
        shutdown() {
            return Promise.resolve();
        },
        forceFlush() {
            return Promise.resolve();
        },
    };
}
